import glob,re,os,subprocess,json
D='.archon-horizon/roadmap/items/'
st={};par={}
for f in glob.glob(D+'*.yaml'):
    i=os.path.basename(f)[:-5]; t=open(f).read()
    m=re.search(r'^status:[ ]*(\S+)',t,re.M); st[i]=m.group(1) if m else '?'
    m=re.search(r'^\s+parent:[ ]*(\S+)',t,re.M); par[i]=m.group(1) if m else ''
act=[i for i in st if st[i]=='active']
out=subprocess.run(['/home/axel/.archon-env/bin/horizon','task','list','--json'],capture_output=True,text=True).stdout
ts=json.loads(out[out.index('{'):]) if '{' in out else {}
ts=ts.get('tasks',ts)
run={t['id']:(t.get('roadmap_refs') or []) for t in ts if t['status']=='running'}
held={}
for tid,refs in run.items():
    for r in refs: held.setdefault(r,[]).append(tid)
def desc_live(i):
    # any descendant held by live lane
    kids=[k for k in par if par[k]==i]
    for k in kids:
        if k in held or desc_live(k): return True
    return False
print('LIVE LANES:',len(run))
for tid,refs in sorted(run.items()):
    mine=[r for r in refs if st.get(r)=='active']
    print(f'  {tid:16s} active rows held: {mine if mine else "NONE"}')
print()
print(f'ACTIVE ROWS: {len(act)}')
orph=[]
for i in sorted(act):
    if i in held: tag='DIRECT ('+','.join(held[i])+')'
    elif desc_live(i): tag='ANCESTOR of a live row'
    elif not par[i]: tag='TOP-LEVEL/north-star?'
    else: tag='*** ORPHAN ***'; orph.append(i)
    print(f'  {i:52s} {tag}')
print()
print('ORPHANS:',orph or 'NONE')
EOF
